function calculateAge(dob) {

    if (!dob) {
        return 0;
    }

    const birth = new Date(dob);
    const today = new Date();

    let age = today.getFullYear() - birth.getFullYear();

    const monthDiff =
        today.getMonth() - birth.getMonth();

    if (
        monthDiff < 0 ||
        (monthDiff === 0 &&
            today.getDate() < birth.getDate())
    ) {
        age--;
    }

    return age;
}

