function formatDOBForCase(dob) {

    if (!dob) {
        return "";
    }

    /*
     * Already DD/MM/YYYY
     */
    if (
        /^\d{2}\/\d{2}\/\d{4}$/.test(dob)
    ) {
        return dob;
    }

    const date = new Date(dob);

    if (isNaN(date.getTime())) {
        throw new Error(
            "Invalid DOB: " + dob
        );
    }

    const dd =
        String(
            date.getDate()
        ).padStart(2, "0");

    const mm =
        String(
            date.getMonth() + 1
        ).padStart(2, "0");

    const yyyy =
        date.getFullYear();

    return `${dd}/${mm}/${yyyy}`;
}

